// HEXA Matrix tracker. Board layout, skill names, Final Damage weights and the
// Sol Erda cost tables all live in hexa_data.js (generated by tools/gen_hexa_data.js).
//
// Saved shape, per tracking id (a classId for the standalone tab, 'char:<id>' for
// a roster character):
//   { classId?, levels: {skillKey: 0..30}, targets: {skillKey: 0..30}, excluded: {skillKey: bool} }
// `levels` is where you are now, `targets` is where you want to end up. Keys match
// the ones written by earlier versions, so existing saves carry over untouched.
// The reserved key `__budget` holds the account-wide weekly farming rate.

const hexaTracker = {
    STORAGE_KEY: 'mapleManager_hexa_v1',
    MAX_LEVEL: 30,
    ICON_BASE: 'assets/hexa_icons/gms/',

    SKILL_TYPE_CONFIG: {
        mastery: { label: 'M', badge: '#f97316', color: '#fdba74', title: 'Mastery' },
        origin:  { label: 'O', badge: '#facc15', color: '#fde68a', title: 'Origin' },
        ascent:  { label: 'A', badge: '#eab308', color: '#fde047', title: 'Ascent' },
        enhance: { label: 'B', badge: '#38bdf8', color: '#7dd3fc', title: 'Boost' },
        common:  { label: 'C', badge: '#a78bfa', color: '#c4b5fd', title: 'Common' },
    },

    // Board tiers, in the order GMS shows them.
    TIERS: [
        { id: 'skillNodes', label: 'Skill Node', color: '#fde68a' },
        { id: 'mastery',    label: 'Mastery',    color: '#fdba74' },
        { id: 'boost',      label: 'Boost',      color: '#7dd3fc' },
        { id: 'common',     label: 'Common',     color: '#c4b5fd' },
    ],

    GROUP_LABELS: {
        EXPLORER: 'Explorer', CYGNUSKIGHT: 'Cygnus Knights',
        HERO: 'Heroes', RESISTANCE: 'Resistance', DEMON: 'Demon',
        NOVA: 'Nova', FLORA: 'Flora', ANIMA: 'Anima',
        FRIENDSWORLD: 'Friendship World', TRANSCENDENT: 'Transcendent',
        SENGOKU: 'Sengoku', JIANGHU: 'Jianghu', SHINE: 'Shine',
    },

    // Weekly farming budget used to turn remaining cost into an ETA. The defaults
    // are the no-grind baseline (dailies only).
    DEFAULT_BUDGET: { frag: 90, erda: 9 },

    currentClassId: null,
    panelTab: 'progress',   // 'progress' | 'priority'
    prioritySort: 'frag',   // 'frag' | 'erda'
    data: {},
    _loaded: false,

    init() {
        this.loadData();
        this.render();
    },

    loadData() {
        try {
            const s = localStorage.getItem(this.STORAGE_KEY);
            if (s) this.data = JSON.parse(s);
        } catch (e) { this.data = {}; }
        this._loaded = true;
    },

    // The character modal can be opened (from the roster) before the HEXA view
    // runs init(); make sure saved data is loaded so we never overwrite it.
    ensureLoaded() {
        if (!this._loaded) this.loadData();
    },

    saveData() {
        try { localStorage.setItem(this.STORAGE_KEY, JSON.stringify(this.data)); } catch (e) {}
    },

    getClassSkills(id) {
        return (window.HEXA_CLASS_SKILLS || []).find(c => c.id === id);
    },

    getClassInfo(id) {
        for (const group of Object.values(window.CLASS_DATA || {})) {
            const f = group.find(c => c.id === id);
            if (f) return f;
        }
        return null;
    },

    getSkillIcon(skill) {
        return skill && skill.icon ? this.ICON_BASE + skill.icon + '.png' : null;
    },

    // ========== Cost model ==========

    // Which HEXA_COST table a node pays from. Origin has its own table because
    // its Lv.1 is granted free when you hit 6th job; the 3rd Common core is
    // cheaper than the first two.
    costKey(skill) {
        if (skill.type === 'origin') return 'origin';
        if (skill.type === 'ascent') return 'ascent';
        if (skill.type === 'mastery') return 'mastery';
        if (skill.type === 'enhance') return 'enhance';
        if (skill.type === 'common') return skill.slot === 2 ? 'common3' : 'common';
        return 'mastery';
    },

    // Lowest level a node can sit at (Origin is auto-granted at Lv.1).
    minLevel(skill) {
        return (window.HEXA_MIN_LEVEL || {})[skill.type] || 0;
    },

    clampLevel(skill, v) {
        const n = parseInt(v, 10);
        return Math.max(this.minLevel(skill), Math.min(this.MAX_LEVEL, isNaN(n) ? 0 : n));
    },

    table(skill) {
        return (window.HEXA_COST || {})[this.costKey(skill)] || (window.HEXA_COST || {}).mastery;
    },

    // Cumulative Sol Erda Fragments spent to sit at `level`.
    fragAt(skill, level) {
        const t = this.table(skill);
        if (!t) return 0;
        return t.frag[Math.max(0, Math.min(this.MAX_LEVEL, level))] || 0;
    },

    // Cumulative Sol Erda spent to sit at `level`.
    erdaAt(skill, level) {
        const t = this.table(skill);
        if (!t) return 0;
        return t.erda[Math.max(0, Math.min(this.MAX_LEVEL, level))] || 0;
    },

    // ========== Final Damage model ==========

    // Share of a node's FD weight unlocked at `level`. Nodes that ship an explicit
    // curve use it; the rest follow the per-tier shape in HEXA_FD_FALLBACK.
    fdAt(skill, level) {
        const n = Math.max(0, Math.min(this.MAX_LEVEL, level));
        if (n <= 0 || !skill.fd) return 0;

        const curves = window.HEXA_FD_CURVES || [];
        if (skill.c >= 0 && curves[skill.c]) {
            const curve = curves[skill.c];
            let total = 0, acc = 0;
            for (let i = 0; i < curve.length; i++) {
                total += curve[i];
                if (i < n) acc += curve[i];
            }
            return total > 0 ? acc / total * skill.fd : 0;
        }

        const f = (window.HEXA_FD_FALLBACK || {})[skill.tier];
        if (!f) return 0;
        let share = f.first;
        share += f.first > 0 ? (n - 1) / 29 * f.slope : n / 30 * f.slope;
        if (n >= 10) share += f.steps[10];
        if (n >= 20) share += f.steps[20];
        if (n >= 30) share += f.steps[30];
        return share * skill.fd;
    },

    // ========== Saved state ==========

    entry(trackingId) {
        return this.data[trackingId] || {};
    },

    // Current level of a node, floored at its auto-granted minimum.
    levelOf(trackingId, skill) {
        const levels = this.entry(trackingId).levels || {};
        return Math.max(this.minLevel(skill), levels[skill.key] || 0);
    },

    // Target level of a node. Unset means "take it to 30".
    targetOf(trackingId, skill) {
        const targets = this.entry(trackingId).targets || {};
        const t = targets[skill.key];
        const v = (typeof t === 'number') ? t : this.MAX_LEVEL;
        return Math.max(this.levelOf(trackingId, skill), Math.min(this.MAX_LEVEL, v));
    },

    isExcluded(trackingId, skill) {
        return !!(this.entry(trackingId).excluded || {})[skill.key];
    },

    // Nodes that count toward progress: released, and not manually excluded.
    activeSkills(trackingId, classId) {
        const cls = this.getClassSkills(classId);
        if (!cls) return [];
        return cls.skills.filter(s => !this.isExcluded(trackingId, s));
    },

    // trackingId selects which saved data set to use; classId selects the board.
    getProgress(trackingId, classId) {
        if (classId === undefined) classId = trackingId;
        const empty = {
            pct: 0, pctToTarget: 0,
            fragSpent: 0, fragMax: 0, fragTarget: 0,
            erdaSpent: 0, erdaMax: 0, erdaTarget: 0,
            fdNow: 0, fdMax: 0, fdTarget: 0,
        };
        if (!this.getClassSkills(classId)) return empty;

        const out = { ...empty };
        for (const s of this.activeSkills(trackingId, classId)) {
            const lv = this.levelOf(trackingId, s);
            const tg = this.targetOf(trackingId, s);
            out.fragSpent += this.fragAt(s, lv);
            out.fragTarget += this.fragAt(s, tg);
            out.fragMax += this.fragAt(s, this.MAX_LEVEL);
            out.erdaSpent += this.erdaAt(s, lv);
            out.erdaTarget += this.erdaAt(s, tg);
            out.erdaMax += this.erdaAt(s, this.MAX_LEVEL);
            out.fdNow += this.fdAt(s, lv);
            out.fdTarget += this.fdAt(s, tg);
            out.fdMax += this.fdAt(s, this.MAX_LEVEL);
        }
        out.pct = out.fragMax > 0 ? Math.round(out.fragSpent / out.fragMax * 100) : 0;
        out.pctToTarget = out.fragTarget > 0 ? Math.round(out.fragSpent / out.fragTarget * 100) : 0;
        return out;
    },

    // ========== Priority: what to level next, by FD per resource ==========

    getBudget() {
        const b = this.data.__budget || {};
        return {
            frag: typeof b.frag === 'number' ? b.frag : this.DEFAULT_BUDGET.frag,
            erda: typeof b.erda === 'number' ? b.erda : this.DEFAULT_BUDGET.erda,
        };
    },

    setBudget(which, value) {
        const n = Math.max(0, parseInt(value, 10) || 0);
        if (!this.data.__budget) this.data.__budget = { ...this.DEFAULT_BUDGET };
        this.data.__budget[which] = n;
        this.saveData();
        this.refreshAll();
    },

    setPrioritySort(kind) {
        this.prioritySort = kind;
        this.refreshAll();
    },

    // Greedy chain from current levels to targets: repeatedly take the single
    // level with the best FD per resource, then merge consecutive levels of the
    // same node into one step (their ratios are equal, so the order is unchanged).
    buildPlan(trackingId, classId) {
        const skills = this.activeSkills(trackingId, classId).filter(s => s.fd > 0);
        const cursor = {};
        const target = {};
        for (const s of skills) {
            cursor[s.key] = this.levelOf(trackingId, s);
            target[s.key] = this.targetOf(trackingId, s);
        }
        const perErda = this.prioritySort === 'erda';

        const singles = [];
        // Bounded by every node's remaining levels, so this always terminates.
        const cap = skills.length * this.MAX_LEVEL;
        for (let guard = 0; guard < cap; guard++) {
            let best = null;
            for (const s of skills) {
                const lv = cursor[s.key];
                if (lv >= target[s.key]) continue;
                const frag = this.fragAt(s, lv + 1) - this.fragAt(s, lv);
                const erda = this.erdaAt(s, lv + 1) - this.erdaAt(s, lv);
                const fd = this.fdAt(s, lv + 1) - this.fdAt(s, lv);
                const cost = perErda ? erda : frag;
                const ratio = cost > 0 ? fd / cost : (fd > 0 ? Infinity : 0);
                if (!best || ratio > best.ratio) best = { skill: s, from: lv, frag, erda, fd, ratio };
            }
            if (!best) break;
            cursor[best.skill.key] = best.from + 1;
            singles.push(best);
        }

        const steps = [];
        for (const step of singles) {
            const last = steps[steps.length - 1];
            if (last && last.skill.key === step.skill.key && last.to === step.from) {
                last.to = step.from + 1;
                last.frag += step.frag;
                last.erda += step.erda;
                last.fd += step.fd;
                continue;
            }
            steps.push({ skill: step.skill, from: step.from, to: step.from + 1, frag: step.frag, erda: step.erda, fd: step.fd, ratio: step.ratio });
        }
        return steps;
    },

    // ========== Rendering ==========

    render() {
        const root = document.getElementById('view-hexa');
        if (!root) return;
        root.innerHTML = this.buildHTML();
        lucide.createIcons();
    },

    buildHTML() {
        return `<div class="flex h-[calc(100vh-7rem)] -m-6">
            <div class="w-56 shrink-0 border-r border-slate-800 overflow-y-auto custom-scrollbar bg-slate-900/50 p-2" id="hexa-class-list">
                ${this.buildClassList()}
            </div>
            <div class="flex-1 flex flex-col min-w-0">
                <div id="hexa-panel-tabs" class="shrink-0 flex items-center gap-1 px-5 pt-3 border-b border-slate-800">
                    ${this.currentClassId ? this.buildTabs('panel') : ''}
                </div>
                <div class="flex-1 overflow-y-auto custom-scrollbar p-5" id="hexa-skill-panel">
                    ${this.currentClassId ? this.buildPanel(this.currentClassId, this.currentClassId, 'panel') : this.buildEmptyState()}
                </div>
            </div>
        </div>`;
    },

    buildClassList() {
        if (!window.CLASS_DATA) return '';
        let html = '';
        for (const [groupId, classes] of Object.entries(CLASS_DATA)) {
            const label = this.GROUP_LABELS[groupId] || groupId;
            const hexaClasses = classes.filter(c => this.getClassSkills(c.id));
            if (!hexaClasses.length) continue;
            html += `<div class="mb-3">
                <div class="text-[9px] text-slate-500 font-bold uppercase tracking-widest px-2 py-1">${this.escHtml(label)}</div>
                <div class="space-y-0.5">`;
            for (const cls of hexaClasses) {
                const isActive = this.currentClassId === cls.id;
                const { pct } = this.getProgress(cls.id, cls.id);
                const pctHtml = pct > 0
                    ? `<span class="text-[9px] font-bold shrink-0" style="color:#8b5cf6">${pct}%</span>`
                    : '';
                html += `<button onclick="hexaTracker.selectClass('${cls.id}')"
                    class="w-full flex items-center gap-2 px-2 py-1.5 rounded-lg text-left transition-colors ${isActive ? 'bg-violet-900/50 text-white' : 'text-slate-400 hover:bg-slate-800 hover:text-slate-200'}">
                    <img src="${cls.path}" class="w-6 h-6 object-contain shrink-0" loading="lazy">
                    <span class="text-xs flex-1 truncate">${this.escHtml(cls.name)}</span>
                    ${pctHtml}
                </button>`;
            }
            html += `</div></div>`;
        }
        return html;
    },

    buildEmptyState() {
        return `<div class="flex items-center justify-center h-full">
            <div class="text-center text-slate-500">
                <i data-lucide="layers" class="w-14 h-14 mx-auto mb-4 opacity-20"></i>
                <p class="text-sm font-medium">左から職業を選択してください</p>
                <p class="text-xs mt-1 opacity-60">HEXAスキルの進捗を管理できます</p>
            </div>
        </div>`;
    },

    // Tab strip shared by the standalone panel and the character modal.
    // `scope` is 'panel' or 'modal' and decides which tab state is read/written.
    buildTabs(scope) {
        const active = scope === 'modal' ? this.modalTab : this.panelTab;
        const tab = (id, label, icon) => `<button onclick="hexaTracker.setTab('${scope}','${id}')"
            class="flex items-center gap-1.5 px-3.5 py-2 text-xs font-bold rounded-t-lg border-b-2 -mb-px transition-colors ${active === id ? 'border-violet-400 text-white' : 'border-transparent text-slate-400 hover:text-slate-200'}">
            <i data-lucide="${icon}" class="w-3.5 h-3.5"></i>${label}
        </button>`;
        return tab('progress', '進捗入力', 'sliders-horizontal') + tab('priority', '効率順', 'trending-up');
    },

    setTab(scope, tab) {
        if (scope === 'modal') this.modalTab = tab; else this.panelTab = tab;
        this.refreshAll();
    },

    buildPanel(classId, trackingId, scope) {
        const tab = scope === 'modal' ? this.modalTab : this.panelTab;
        return tab === 'priority'
            ? this.buildPriority(classId, trackingId)
            : this.buildSkillPanel(classId, trackingId);
    },

    buildSkillPanel(classId, trackingId) {
        if (classId === undefined) classId = this.currentClassId;
        if (trackingId === undefined) trackingId = classId;
        const cls = this.getClassSkills(classId);
        const info = this.getClassInfo(classId);
        if (!cls || !info) return this.buildEmptyState();

        const p = this.getProgress(trackingId, classId);
        const pctColor = p.pct >= 80 ? '#4ade80' : p.pct >= 50 ? '#a78bfa' : '#818cf8';
        const targetPct = p.fragMax > 0 ? Math.round(p.fragTarget / p.fragMax * 100) : 0;
        const remFrag = Math.max(0, p.fragTarget - p.fragSpent);
        const remErda = Math.max(0, p.erdaTarget - p.erdaSpent);

        let groups = '';
        for (const tier of this.TIERS) {
            groups += this.buildSkillGroup(tier, cls, trackingId, classId);
        }

        return `<div class="max-w-4xl mx-auto">
            <div class="flex items-center gap-5 mb-5 bg-slate-900 rounded-xl p-4 border border-slate-800">
                <img src="${info.path}" class="w-16 h-16 object-contain shrink-0" loading="lazy">
                <div class="flex-1 min-w-0">
                    <div class="text-base font-bold text-white">${this.escHtml(info.name)}</div>
                    <div class="text-xs text-slate-500 mb-2">左が現在地、右が目標値。ゲージの濃い部分が現在地、薄い部分が目標までの残りです。</div>
                    <div class="flex items-center gap-3">
                        <div class="relative flex-1 h-2.5 bg-slate-800 rounded-full overflow-hidden">
                            <div class="absolute inset-y-0 left-0 rounded-full bg-violet-500/25" style="width:${targetPct}%"></div>
                            <div id="hexa-pbar" class="absolute inset-y-0 left-0 rounded-full transition-all duration-500"
                                style="width:${p.pct}%; background:linear-gradient(90deg,#7c3aed,#8b5cf6)"></div>
                        </div>
                        <span id="hexa-pct" class="text-lg font-bold w-14 text-right" style="color:${pctColor}">${p.pct}%</span>
                    </div>
                    <div id="hexa-count" class="flex flex-wrap items-center gap-x-3 gap-y-1 text-[11px] mt-1.5">
                        <span class="flex items-center gap-1 text-violet-300" title="ソルエルダフラグメント">
                            <span class="inline-block w-2 h-2 rounded-full" style="background:#a78bfa"></span>
                            フラグメント <span class="font-bold tabular-nums">${p.fragSpent.toLocaleString()}</span>
                            <span class="text-slate-500">/ 目標 ${p.fragTarget.toLocaleString()} / 最大 ${p.fragMax.toLocaleString()}</span>
                        </span>
                        <span class="flex items-center gap-1 text-amber-300" title="ソルエルダ">
                            <span class="inline-block w-2 h-2 rounded-full" style="background:#fcd34d"></span>
                            エルダ <span class="font-bold tabular-nums">${p.erdaSpent.toLocaleString()}</span>
                            <span class="text-slate-500">/ 目標 ${p.erdaTarget.toLocaleString()} / 最大 ${p.erdaMax.toLocaleString()}</span>
                        </span>
                    </div>
                    <div class="flex flex-wrap items-center gap-x-3 gap-y-1 text-[11px] mt-1">
                        <span class="text-slate-400">目標まで残り
                            <span class="font-bold tabular-nums text-violet-200">${remFrag.toLocaleString()}</span> フラグメント /
                            <span class="font-bold tabular-nums text-amber-200">${remErda.toLocaleString()}</span> エルダ</span>
                        <span class="text-slate-400">最終ダメージ
                            <span class="font-bold tabular-nums text-emerald-300">+${p.fdNow.toFixed(1)}%</span>
                            <span class="text-slate-500">/ 目標 +${p.fdTarget.toFixed(1)}% / 最大 +${p.fdMax.toFixed(1)}%</span></span>
                    </div>
                </div>
            </div>

            <div class="grid grid-cols-2 gap-3">${groups}</div>
        </div>`;
    },

    buildSkillGroup(tier, cls, trackingId, classId) {
        const skills = cls.skills.filter(s => s.tier === tier.id);
        const slots = (cls.slots || {})[tier.id] || skills.length;
        if (!skills.length && slots <= 0) return '';

        let rows = '';
        for (const s of skills) {
            const sCfg = this.SKILL_TYPE_CONFIG[s.type] || this.SKILL_TYPE_CONFIG.mastery;
            const lvl = this.levelOf(trackingId, s);
            const tgt = this.targetOf(trackingId, s);
            const isExcl = this.isExcluded(trackingId, s);
            const fragNow = this.fragAt(s, lvl);
            const fragTgt = this.fragAt(s, tgt);
            const fragMax = this.fragAt(s, this.MAX_LEVEL);
            const pct = fragMax > 0 ? Math.round(fragNow / fragMax * 100) : 0;
            const tgtPct = fragMax > 0 ? Math.round(fragTgt / fragMax * 100) : 0;
            const iconUrl = this.getSkillIcon(s);
            const iconHtml = iconUrl
                ? `<img src="${iconUrl}" class="w-6 h-6 object-contain shrink-0 rounded" loading="lazy" alt="">`
                : `<div class="w-6 h-6 rounded-full flex items-center justify-center text-[10px] font-bold text-white shrink-0" style="background:${sCfg.badge}">${sCfg.label}</div>`;
            const fdHint = s.fd > 0 ? ` · 最大 +${s.fd.toFixed(2)}% FD` : '';

            rows += `<div class="flex items-center gap-2 py-1.5 border-b border-slate-800/50 last:border-0 ${isExcl ? 'opacity-40' : ''}">
                ${iconHtml}
                <div class="flex-1 min-w-0">
                    <div class="flex items-baseline justify-between gap-1.5">
                        <div class="text-[11px] text-slate-300 leading-snug truncate" title="${this.escHtml(s.name)}${fdHint}">${this.escHtml(s.name)}</div>
                        <div class="text-[9px] text-slate-500 shrink-0 tabular-nums" title="ソルエルダフラグメント（現在 / 目標）">${isExcl ? '除外' : fragNow.toLocaleString()}</div>
                    </div>
                    <div class="relative h-1 bg-slate-700/60 rounded-full mt-1 overflow-hidden">
                        <div class="absolute inset-y-0 left-0 rounded-full opacity-40" style="width:${isExcl ? 0 : tgtPct}%;background:${sCfg.badge}"></div>
                        <div class="absolute inset-y-0 left-0 rounded-full transition-all" style="width:${isExcl ? 0 : pct}%;background:${sCfg.badge}"></div>
                    </div>
                </div>
                <input type="number" min="${this.minLevel(s)}" max="${this.MAX_LEVEL}" value="${lvl}" title="現在地"
                    oninput="hexaTracker.updateLevel('${trackingId}','${classId}','${s.key}',this.value)"
                    class="w-10 bg-slate-800 border border-slate-700 rounded text-center text-xs text-white py-0.5 focus:outline-none focus:border-violet-500 shrink-0">
                <span class="text-[10px] text-slate-600 shrink-0">→</span>
                <input type="number" min="${this.minLevel(s)}" max="${this.MAX_LEVEL}" value="${tgt}" title="目標値"
                    oninput="hexaTracker.updateTarget('${trackingId}','${classId}','${s.key}',this.value)"
                    class="w-10 bg-slate-950 border border-violet-800/70 rounded text-center text-xs text-violet-200 py-0.5 focus:outline-none focus:border-violet-500 shrink-0">
                <button onclick="hexaTracker.toggleExclude('${trackingId}','${s.key}')"
                    title="${isExcl ? '進捗に含める' : '進捗から除外'}"
                    class="w-5 h-5 rounded border flex items-center justify-center shrink-0 transition-colors ${isExcl ? 'bg-slate-700 border-slate-600' : 'border-slate-600 hover:border-slate-400 hover:bg-slate-800'}">
                    ${isExcl ? `<svg viewBox="0 0 12 12" width="10" height="10"><line x1="2" y1="2" x2="10" y2="10" stroke="#94a3b8" stroke-width="1.5"/><line x1="10" y1="2" x2="2" y2="10" stroke="#94a3b8" stroke-width="1.5"/></svg>` : ''}
                </button>
            </div>`;
        }

        // Board slots GMS has not released yet, shown so the layout matches in-game.
        const pending = Math.max(0, slots - skills.length);
        for (let i = 0; i < pending; i++) {
            rows += `<div class="flex items-center gap-2 py-1.5 border-b border-slate-800/50 last:border-0">
                <div class="w-6 h-6 rounded border border-dashed border-slate-700 shrink-0"></div>
                <div class="flex-1 text-[10px] text-slate-600 tracking-widest uppercase">未実装</div>
            </div>`;
        }

        return `<div class="bg-slate-900 rounded-xl border border-slate-800 p-3">
            <div class="text-[10px] font-bold uppercase tracking-wider mb-2" style="color:${tier.color}">${tier.label}</div>
            <div>${rows}</div>
        </div>`;
    },

    // Ranked "what to level next", by Final Damage gained per Sol Erda Fragment
    // (or per Sol Erda). Runs from the entered current levels up to the targets.
    buildPriority(classId, trackingId) {
        const cls = this.getClassSkills(classId);
        const info = this.getClassInfo(classId);
        if (!cls || !info) return this.buildEmptyState();

        const steps = this.buildPlan(trackingId, classId);
        const budget = this.getBudget();
        const perErda = this.prioritySort === 'erda';

        const sortBtn = (kind, label, hint) => `<button onclick="hexaTracker.setPrioritySort('${kind}')" title="${hint}"
            class="px-3 py-1 text-[11px] font-bold rounded-md transition-colors ${this.prioritySort === kind ? 'bg-violet-600 text-white' : 'text-slate-400 hover:text-slate-200'}">${label}</button>`;

        const header = `<div class="bg-slate-900 rounded-xl border border-slate-800 p-3 mb-4">
            <div class="flex flex-wrap items-center justify-between gap-3">
                <div class="inline-flex rounded-lg bg-slate-800 p-0.5 border border-slate-700">
                    ${sortBtn('frag', 'フラグメント効率', '最終ダメージ / ソルエルダフラグメント で並べ替え')}
                    ${sortBtn('erda', 'エルダ効率', '最終ダメージ / ソルエルダ で並べ替え')}
                </div>
                <div class="flex items-center gap-3 text-[11px] text-slate-400">
                    <label class="flex items-center gap-1.5" title="1週間に入手するソルエルダフラグメント">
                        <span class="inline-block w-2 h-2 rounded-full" style="background:#a78bfa"></span>
                        <input type="number" min="0" value="${budget.frag}" oninput="hexaTracker.setBudget('frag',this.value)"
                            class="w-16 bg-slate-800 border border-slate-700 rounded text-center text-xs text-white py-0.5 focus:outline-none focus:border-violet-500"> / 週
                    </label>
                    <label class="flex items-center gap-1.5" title="1週間に入手するソルエルダ">
                        <span class="inline-block w-2 h-2 rounded-full" style="background:#fcd34d"></span>
                        <input type="number" min="0" value="${budget.erda}" oninput="hexaTracker.setBudget('erda',this.value)"
                            class="w-16 bg-slate-800 border border-slate-700 rounded text-center text-xs text-white py-0.5 focus:outline-none focus:border-violet-500"> / 週
                    </label>
                </div>
            </div>
        </div>`;

        if (!steps.length) {
            return `<div class="max-w-4xl mx-auto">${header}
                <div class="flex items-center justify-center h-40 text-center text-slate-500">
                    <div><i data-lucide="check-circle-2" class="w-10 h-10 mx-auto mb-3 opacity-30"></i>
                    <p class="text-sm">目標値に到達済みです</p>
                    <p class="text-xs mt-1 opacity-70">進捗入力タブで目標値を上げると、ここに次の一手が並びます。</p></div>
                </div></div>`;
        }

        let cumFrag = 0, cumErda = 0, cumFd = 0;
        let rows = '';
        steps.forEach((step, i) => {
            cumFrag += step.frag; cumErda += step.erda; cumFd += step.fd;
            const s = step.skill;
            const sCfg = this.SKILL_TYPE_CONFIG[s.type] || this.SKILL_TYPE_CONFIG.mastery;
            const iconUrl = this.getSkillIcon(s);
            const iconHtml = iconUrl
                ? `<img src="${iconUrl}" class="w-8 h-8 object-contain shrink-0 rounded" loading="lazy" alt="">`
                : `<div class="w-8 h-8 rounded-full flex items-center justify-center text-[11px] font-bold text-white shrink-0" style="background:${sCfg.badge}">${sCfg.label}</div>`;

            // Weeks to afford everything up to and including this step; whichever
            // resource runs out last is the one that gates you.
            const wFrag = budget.frag > 0 ? cumFrag / budget.frag : Infinity;
            const wErda = budget.erda > 0 ? cumErda / budget.erda : Infinity;
            const weeks = Math.max(wFrag, wErda);
            const gate = wErda > wFrag ? 'エルダ待ち' : 'フラグメント待ち';
            const eta = Number.isFinite(weeks) ? `${Math.ceil(weeks)}週（${gate}）` : '—';
            const levels = step.to - step.from;

            rows += `<div class="flex items-center gap-3 py-2 px-2.5 rounded-lg ${i % 2 ? 'bg-slate-900/40' : ''}">
                <span class="w-6 text-right text-[11px] font-bold text-slate-500 tabular-nums shrink-0">${i + 1}</span>
                ${iconHtml}
                <div class="flex-1 min-w-0">
                    <div class="flex items-baseline gap-2">
                        <span class="text-xs text-slate-200 truncate" title="${this.escHtml(s.name)}">${this.escHtml(s.name)}</span>
                        <span class="text-[9px] font-bold uppercase tracking-wider shrink-0" style="color:${sCfg.color}">${sCfg.title}</span>
                    </div>
                    <div class="text-[10px] text-slate-500 tabular-nums">
                        Lv.${step.from} → ${step.to}${levels > 1 ? `（${levels}段階）` : ''}
                        · <span class="text-violet-300">${step.frag.toLocaleString()}</span> フラグメント
                        · <span class="text-amber-300">${step.erda.toLocaleString()}</span> エルダ
                        · 累計 ${eta}
                    </div>
                </div>
                <div class="text-right shrink-0">
                    <div class="text-sm font-bold text-emerald-300 tabular-nums">+${step.fd.toFixed(2)}%</div>
                    <div class="text-[9px] text-slate-500 tabular-nums" title="${perErda ? 'エルダ1あたりの最終ダメージ' : 'フラグメント100あたりの最終ダメージ'}">
                        ${perErda ? (step.erda > 0 ? (step.fd / step.erda).toFixed(3) : '—') + ' /エルダ'
                                  : (step.frag > 0 ? (step.fd / step.frag * 100).toFixed(3) : '—') + ' /100frag'}
                    </div>
                </div>
            </div>`;
        });

        const totalWeeks = Math.max(
            budget.frag > 0 ? cumFrag / budget.frag : Infinity,
            budget.erda > 0 ? cumErda / budget.erda : Infinity,
        );

        return `<div class="max-w-4xl mx-auto">
            ${header}
            <div class="flex flex-wrap items-center gap-x-4 gap-y-1 text-[11px] text-slate-400 mb-2 px-1">
                <span>全${steps.length}ステップ</span>
                <span class="text-violet-300">フラグメント計 <span class="font-bold tabular-nums">${cumFrag.toLocaleString()}</span></span>
                <span class="text-amber-300">エルダ計 <span class="font-bold tabular-nums">${cumErda.toLocaleString()}</span></span>
                <span class="text-emerald-300">最終ダメージ計 <span class="font-bold tabular-nums">+${cumFd.toFixed(1)}%</span></span>
                <span>${Number.isFinite(totalWeeks) ? `約${Math.ceil(totalWeeks)}週` : '—'}</span>
            </div>
            <div class="bg-slate-900/40 border border-slate-800 rounded-xl p-2 divide-y divide-slate-800/40">${rows}</div>
            <p class="text-[10px] text-slate-600 mt-3 leading-relaxed">
                現在地から目標値まで、1レベルずつ「最終ダメージ / 消費リソース」が最大の一手を選び続けた順序です。
                同じスキルの連続レベルは1ステップにまとめています。リソース消費量は正確な値、最終ダメージ量はノード係数からの推定値です。
            </p>
        </div>`;
    },

    selectClass(classId) {
        this.currentClassId = classId;
        this.refreshAll();
    },

    // Re-render every live HEXA surface (standalone tab panel/list + character modal body).
    refreshAll() {
        const panel = document.getElementById('hexa-skill-panel');
        if (panel && this.currentClassId) panel.innerHTML = this.buildPanel(this.currentClassId, this.currentClassId, 'panel');
        const panelTabs = document.getElementById('hexa-panel-tabs');
        if (panelTabs) panelTabs.innerHTML = this.currentClassId ? this.buildTabs('panel') : '';
        const list = document.getElementById('hexa-class-list');
        if (list) list.innerHTML = this.buildClassList();
        const mtabs = document.getElementById('hexa-modal-tabs');
        if (mtabs && this.modalClassId) mtabs.innerHTML = this.buildTabs('modal');
        const mcontent = document.getElementById('hexa-modal-content');
        if (mcontent && this.modalClassId) mcontent.innerHTML = this.buildModalContent();
        const mhead = document.getElementById('hexa-modal-progress');
        if (mhead && this.modalTrackingId) mhead.innerHTML = this.buildModalHeaderStat();
        if (window.lucide) lucide.createIcons();
    },

    ensureEntry(trackingId) {
        if (!this.data[trackingId]) this.data[trackingId] = { levels: {}, targets: {}, excluded: {} };
        const e = this.data[trackingId];
        if (!e.levels) e.levels = {};
        if (!e.targets) e.targets = {};
        if (!e.excluded) e.excluded = {};
        return e;
    },

    findSkill(classId, skillKey) {
        const cls = this.getClassSkills(classId);
        return cls ? cls.skills.find(s => s.key === skillKey) : null;
    },

    updateLevel(trackingId, classId, skillKey, value) {
        const skill = this.findSkill(classId, skillKey);
        if (!skill) return;
        const e = this.ensureEntry(trackingId);
        const lvl = this.clampLevel(skill, value);
        e.levels[skillKey] = lvl;
        // A target below the current level is meaningless; pull it up with you.
        if (typeof e.targets[skillKey] === 'number' && e.targets[skillKey] < lvl) e.targets[skillKey] = lvl;
        this.saveData();
        this.refreshAll();
    },

    updateTarget(trackingId, classId, skillKey, value) {
        const skill = this.findSkill(classId, skillKey);
        if (!skill) return;
        const e = this.ensureEntry(trackingId);
        const cur = Math.max(this.minLevel(skill), e.levels[skillKey] || 0);
        e.targets[skillKey] = Math.max(cur, this.clampLevel(skill, value));
        this.saveData();
        this.refreshAll();
    },

    toggleExclude(trackingId, skillKey) {
        const e = this.ensureEntry(trackingId);
        e.excluded[skillKey] = !e.excluded[skillKey];
        this.saveData();
        this.refreshAll();
    },

    // ========== Character-linked modal ==========
    modalCharId: null,
    modalClassId: null,
    modalTrackingId: null,
    modalTab: 'progress',   // 'progress' | 'priority'

    // Resolve a dashboard character's job name to a HEXA classId (or null if no HEXA data).
    resolveClassId(jobName) {
        if (!jobName || typeof window === 'undefined' || !window.CLASS_DATA) return null;
        const norm = s => String(s).toLowerCase().replace(/[^a-z0-9]/g, '');
        const target = norm(jobName);
        for (const arr of Object.values(window.CLASS_DATA)) {
            const m = arr.find(j => norm(j.name) === target || norm(j.id) === target);
            if (m && this.getClassSkills(m.id)) return m.id;
        }
        return null;
    },

    // Resolve the HEXA classId for a character: manual assignment first, then auto-match by job name.
    getCharClassId(char) {
        if (!char) return null;
        const saved = this.data['char:' + char.id];
        if (saved && saved.classId && this.getClassSkills(saved.classId)) return saved.classId;
        return this.resolveClassId(char.job);
    },

    openForCharacter(charId) {
        this.ensureLoaded();
        const char = (window.app && window.app.data && window.app.data.characters || []).find(c => c.id === charId);
        if (!char) return;
        const classId = this.getCharClassId(char);
        if (!classId) {
            // No HEXA class linked yet — let the user register one.
            this.openClassPicker(charId);
            return;
        }
        this.modalCharId = charId;
        this.modalClassId = classId;
        this.modalTrackingId = 'char:' + charId;
        this.renderModal(char);
    },

    // Shared overlay element + Escape handler for any HEXA modal/picker.
    ensureOverlay() {
        let overlay = document.getElementById('hexa-modal-overlay');
        if (!overlay) {
            overlay = document.createElement('div');
            overlay.id = 'hexa-modal-overlay';
            document.body.appendChild(overlay);
        }
        overlay.className = 'fixed inset-0 z-[200] flex items-center justify-center bg-black/70 backdrop-blur-sm p-4';
        overlay.setAttribute('onclick', 'if(event.target===this)hexaTracker.closeModal()');
        if (!this._escHandler) {
            this._escHandler = (e) => { if (e.key === 'Escape') this.closeModal(); };
            document.addEventListener('keydown', this._escHandler);
        }
        return overlay;
    },

    // Class registration picker for characters whose job can't be auto-matched (or to re-assign).
    openClassPicker(charId) {
        this.ensureLoaded();
        const char = (window.app && window.app.data && window.app.data.characters || []).find(c => c.id === charId);
        if (!char) return;
        const guess = this.resolveClassId(char.job);
        const current = this.getCharClassId(char);
        let groupsHtml = '';
        if (window.CLASS_DATA) {
            for (const [groupId, classes] of Object.entries(CLASS_DATA)) {
                const hexaClasses = classes.filter(c => this.getClassSkills(c.id));
                if (!hexaClasses.length) continue;
                const label = this.GROUP_LABELS[groupId] || groupId;
                let cards = '';
                for (const cls of hexaClasses) {
                    const sel = (cls.id === current);
                    cards += `<button onclick="hexaTracker.assignClass('${charId}','${cls.id}')"
                        title="${this.escHtml(cls.name)}"
                        class="flex flex-col items-center gap-1 p-2 rounded-lg border transition-colors ${sel ? 'bg-violet-700/40 border-violet-400 ring-1 ring-violet-400' : 'bg-slate-800/60 border-slate-700 hover:bg-violet-700/30 hover:border-violet-500'}">
                        <img src="${cls.path}" class="w-9 h-9 object-contain" loading="lazy">
                        <span class="text-[9px] text-slate-300 text-center leading-tight">${this.escHtml(cls.name)}</span>
                    </button>`;
                }
                groupsHtml += `<div class="mb-3">
                    <div class="text-[9px] text-slate-500 font-bold uppercase tracking-widest mb-1.5">${this.escHtml(label)}</div>
                    <div class="grid grid-cols-5 sm:grid-cols-6 gap-1.5">${cards}</div>
                </div>`;
            }
        }
        const overlay = this.ensureOverlay();
        overlay.innerHTML = `
            <div class="bg-slate-900 border border-violet-500/40 rounded-2xl shadow-2xl w-full max-w-2xl max-h-[85vh] flex flex-col overflow-hidden">
                <div class="flex items-center justify-between gap-3 px-5 py-3 bg-gradient-to-r from-violet-700 via-indigo-600 to-blue-700 shrink-0">
                    <div class="min-w-0">
                        <div class="text-white font-extrabold text-sm truncate flex items-center gap-2"><i data-lucide="hexagon" class="w-4 h-4 shrink-0"></i>${this.escHtml(char.name)} — HEXA職業を登録</div>
                        <div class="text-[11px] text-violet-100 mt-0.5">進捗を管理する職業を選択してください${char.job ? `（現在の職業: ${this.escHtml(char.job)}${guess ? '' : ' — 自動判定できませんでした'}）` : ''}</div>
                    </div>
                    <button onclick="hexaTracker.closeModal()" title="閉じる" class="shrink-0 w-8 h-8 rounded-lg bg-white/10 hover:bg-white/25 text-white flex items-center justify-center transition-colors"><i data-lucide="x" class="w-4 h-4"></i></button>
                </div>
                <div class="overflow-y-auto custom-scrollbar p-4 flex-1">${groupsHtml || '<p class="text-slate-500 text-sm text-center py-8">職業データがありません</p>'}</div>
            </div>`;
        if (window.lucide) lucide.createIcons();
    },

    // Save a manual class assignment for a character, then open its progress modal.
    assignClass(charId, classId) {
        const tid = 'char:' + charId;
        this.ensureEntry(tid).classId = classId;
        this.saveData();
        this.openForCharacter(charId);
        this.refreshRoster();
    },

    buildModalHeaderStat() {
        const p = this.getProgress(this.modalTrackingId, this.modalClassId);
        return `<span class="font-bold tabular-nums">${p.pct}%</span>
            <span class="text-violet-200/80">·</span>
            <span class="tabular-nums">${p.fragSpent.toLocaleString()} / ${p.fragTarget.toLocaleString()}</span>
            <span class="text-violet-200/80">フラグメント（目標比）</span>
            <span class="text-violet-200/80">·</span>
            <span class="tabular-nums">+${p.fdNow.toFixed(1)}%</span>
            <span class="text-violet-200/80">FD</span>`;
    },

    buildModalContent() {
        return this.buildPanel(this.modalClassId, this.modalTrackingId, 'modal');
    },

    renderModal(char) {
        const info = this.getClassInfo(this.modalClassId) || {};
        const portrait = (char.image && char.image.startsWith('http')) ? char.image : (char.classImage || info.path || '');
        const overlay = this.ensureOverlay();
        overlay.innerHTML = `
            <div class="bg-slate-900 border border-violet-500/40 rounded-2xl shadow-2xl w-full max-w-4xl max-h-[90vh] flex flex-col overflow-hidden">
                <div class="flex items-center justify-between gap-3 px-5 py-3 bg-gradient-to-r from-violet-700 via-indigo-600 to-blue-700 shrink-0">
                    <div class="flex items-center gap-3 min-w-0">
                        ${portrait ? `<img src="${portrait}" class="w-11 h-11 rounded-lg object-cover bg-slate-950/40 shrink-0">` : ''}
                        <div class="min-w-0">
                            <div class="text-white font-extrabold text-sm truncate flex items-center gap-2">
                                <i data-lucide="hexagon" class="w-4 h-4 shrink-0"></i>${this.escHtml(char.name)}
                                ${char.level ? `<span class="text-[11px] font-mono font-bold text-violet-100/90">Lv.${this.escHtml(char.level)}</span>` : ''}
                            </div>
                            <div id="hexa-modal-progress" class="text-[11px] text-violet-100 flex items-center gap-1.5 mt-0.5">${this.buildModalHeaderStat()}</div>
                        </div>
                    </div>
                    <div class="flex items-center gap-1.5 shrink-0">
                        <button onclick="hexaTracker.openClassPicker('${this.modalCharId}')" title="HEXA職業を変更" class="w-8 h-8 rounded-lg bg-white/10 hover:bg-white/25 text-white flex items-center justify-center transition-colors">
                            <i data-lucide="repeat" class="w-4 h-4"></i>
                        </button>
                        <button onclick="hexaTracker.closeModal()" title="閉じる" class="w-8 h-8 rounded-lg bg-white/10 hover:bg-white/25 text-white flex items-center justify-center transition-colors">
                            <i data-lucide="x" class="w-4 h-4"></i>
                        </button>
                    </div>
                </div>
                <div id="hexa-modal-body" class="flex-1 flex flex-col min-h-0">
                    <div id="hexa-modal-tabs" class="shrink-0 flex items-center gap-1 px-4 pt-3 border-b border-slate-800">
                        ${this.buildTabs('modal')}
                    </div>
                    <div id="hexa-modal-content" class="overflow-y-auto custom-scrollbar p-5 flex-1">
                        ${this.buildModalContent()}
                    </div>
                </div>
            </div>`;
        if (window.lucide) lucide.createIcons();
    },

    closeModal() {
        const overlay = document.getElementById('hexa-modal-overlay');
        if (overlay) overlay.remove();
        if (this._escHandler) { document.removeEventListener('keydown', this._escHandler); this._escHandler = null; }
        this.modalCharId = null;
        this.modalClassId = null;
        this.modalTrackingId = null;
        this.refreshRoster();
    },

    // Refresh both the roster cards and the dashboard so HEXA badges reflect the latest progress.
    refreshRoster() {
        if (!window.app) return;
        if (typeof window.app.renderCharacters === 'function') window.app.renderCharacters();
        if (typeof window.app.renderDashboard === 'function') window.app.renderDashboard();
    },

    escHtml(s) {
        return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
    },
};
